insert into design_style_prompts(style_key, style_name, prompt) values
('mid-century', '中古风', 'Mid-century modern interior: warm walnut furniture with tapered legs, sculptural but practical forms, muted olive and rust accents, natural wood grain, textured upholstery, vintage-inspired lighting, balanced negative space and contemporary residential comfort. Avoid period-set styling, clutter and excessive ornament.'),
('bauhaus', '包豪斯', 'Bauhaus-inspired contemporary interior: functional geometric forms, clean circles and straight lines, primary-color accents used sparingly, tubular steel details, honest wood and stone materials, modular furniture and clear spatial organization. Keep it warm and livable, not a gallery or industrial workspace.'),
('italian-minimal', '意式极简', 'Contemporary Italian minimalist interior: monolithic natural stone, refined dark oak, warm neutral plaster, low-profile sculptural furniture, precise shadow gaps, restrained metal details and layered architectural lighting. Emphasize proportion, material quality and calm luxury; avoid clutter and excessive decoration.');
